import java.io.*;import java.util.*;class Result {public static int commonChild(String s1, String s2) {int n = s1.length();int[] prev = new int[n + 1];int[] curr = new int[n + 1];for (int i = 1; i <= n; i++) {for (int j = 1; j <= n; j++) {if (s1.charAt(i - 1) == s2.charAt(j - 1)) {curr[j] = prev[j - 1] + 1;} else {curr[j] = Math.max(prev[j], curr[j - 1]);}}System.arraycopy(curr, 0, prev, 0, n + 1);}return prev[n];}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));String s1 = bufferedReader.readLine();String s2 = bufferedReader.readLine();int result = Result.commonChild(s1, s2);String outputPath = System.getenv("OUTPUT_PATH");if (outputPath != null) {BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(outputPath));bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedWriter.close();} else {System.out.println(result);}bufferedReader.close();}}